-- Private intake only. No moderator grants, sanctions, automatic hide, or operating evidence seed.
CREATE TABLE community_report_cases(case_id TEXT PRIMARY KEY,reporter_account_id TEXT NOT NULL REFERENCES accounts(id),target_type TEXT NOT NULL CHECK(target_type IN ('POST','COMMENT')),target_id TEXT NOT NULL,target_revision INTEGER NOT NULL CHECK(target_revision>0),status TEXT NOT NULL CHECK(status IN ('OPEN','IN_REVIEW','ACTIONED','DISMISSED')),revision INTEGER NOT NULL CHECK(revision>0),submitted_at INTEGER NOT NULL CHECK(submitted_at>=0),original_receipt_id TEXT NOT NULL,original_receipt_json TEXT NOT NULL CHECK(json_valid(original_receipt_json)),final_notified_at INTEGER);
CREATE UNIQUE INDEX idx_community_open_report ON community_report_cases(reporter_account_id,target_type,target_id) WHERE status IN ('OPEN','IN_REVIEW');
CREATE TABLE community_report_receipts(account_id TEXT NOT NULL REFERENCES accounts(id),command_id TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES community_report_cases(case_id),request_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),PRIMARY KEY(account_id,command_id));
-- Quota source is independent of evidence/case retirement. Only successful new cases write this event.
CREATE TABLE community_report_creation(case_id TEXT PRIMARY KEY,account_id TEXT NOT NULL,created_at INTEGER NOT NULL CHECK(created_at>=0),expires_at INTEGER NOT NULL);
CREATE INDEX idx_community_report_rate ON community_report_creation(account_id,created_at);
CREATE TABLE community_report_evidence(case_id TEXT PRIMARY KEY REFERENCES community_report_cases(case_id),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),snapshot_hash TEXT NOT NULL,reason_code TEXT NOT NULL,optional_description TEXT,retention_policy_version TEXT NOT NULL,necessity_review_due_at INTEGER NOT NULL,final_notified_at INTEGER,retain_until INTEGER);
-- Final notice starts the approved <=90-day evidence ceiling. Intake does not invent a final notice or purge completion.